package com.hbm.client.oilextraction;
import com.hbm.machine.oilextraction.*;import mezz.jei.api.*;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class OilExtractionJeiPlugin implements IModPlugin {
 static final RecipeType<OilExtractionViews.Extraction> TYPE=RecipeType.create("hbm","oil_extraction",OilExtractionViews.Extraction.class);@Override public ResourceLocation getPluginUid(){return ResourceLocation.parse("hbm:oil_extraction_jei");}@Override public void registerCategories(IRecipeCategoryRegistration e){e.addRecipeCategories(new Category(e.getJeiHelpers().getGuiHelper()));}@Override public void registerRecipes(IRecipeRegistration e){e.addRecipes(TYPE,OilExtractionViews.recipes());}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration e){for(var item:OilExtractionContent.ITEM.values())e.addRecipeCatalysts(TYPE,item.get());}
 private static final class Category implements IRecipeCategory<OilExtractionViews.Extraction>{final IDrawable background,icon;Category(IGuiHelper h){background=h.createBlankDrawable(166,84);icon=h.createDrawableItemStack(new ItemStack(OilExtractionContent.ITEM.get(OilDrillKind.WELL).get()));}@Override public RecipeType<OilExtractionViews.Extraction> getRecipeType(){return TYPE;}@Override public Component getTitle(){return Component.translatable("recipe.hbm.oil_extraction");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder b,OilExtractionViews.Extraction r,IFocusGroup focus){b.addSlot(RecipeIngredientRole.CATALYST,8,24).addItemStack(r.deposit()).addRichTooltipCallback((slot,t)->t.add(OilExtractionViews.depletion(r)));b.addSlot(RecipeIngredientRole.CATALYST,38,24).addItemStack(new ItemStack(OilExtractionContent.ITEM.get(r.kind()).get()));b.addSlot(RecipeIngredientRole.OUTPUT,92,15).addItemStack(r.oil());b.addSlot(RecipeIngredientRole.OUTPUT,120,15).addItemStack(r.gas()).addRichTooltipCallback((slot,t)->t.add(OilExtractionViews.gas(r)));b.addSlot(RecipeIngredientRole.OUTPUT,92,43).addItemStack(r.depleted()).addRichTooltipCallback((slot,t)->t.add(OilExtractionViews.depletion(r)));}@Override public void draw(OilExtractionViews.Extraction r,IRecipeSlotsView slots,GuiGraphics g,double x,double y){g.drawString(com.hbm.client.gui.font.LegacyFonts.get(),Component.translatable("gui.hbm.oil_drill.interval",r.config().delay()),3,66,0x404040,false);g.drawString(com.hbm.client.gui.font.LegacyFonts.get(),Component.translatable("gui.hbm.oil_drill.consumption",r.config().consumption()),3,76,0x404040,false);}}
}
